olor3 = Color3.fromRGB(255, 255, 255)\n    btn.Font = Enum.Font.GothamBold\n    btn.TextSize = 14\n    \n    local corner = Instance.new(\"UICorner\", btn)\n    corner.CornerRadius = UDim.new(0, 10)\n    \n    local function toggle()\n        SETTINGS[setting] = not SETTINGS[setting]\n        btn.BackgroundColor3 = SETTINGS[setting] and Color3.fromRGB(100, 40, 180) or Color3.fromRGB(35, 30, 50)\n        \n        if setting == \"ENABLE_LOCK\" then\n            updateCircleVisibility()\n        elseif setting == \"ENABLE_FLY\" then\n            if SETTINGS.ENABLE_FLY then startFly() else stopFly() end\n        elseif setting == \"ENABLE_NOCLIP\" then\n            if SETTINGS.ENABLE_NOCLIP then startNoclip() else stopNoclip() end\n        elseif setting == \"ENABLE_ESP\" or setting == \"ENABLE_XRAY\" then\n            refreshESP()\n        elseif setting == \"ENABLE_DARK_TEXTURE\" then\n            if SETTINGS.ENABLE_DARK_TEXTURE then startDarkTexture() else stopDarkTexture() end\n        elseif setting == \"ENABLE_UNLOCK_ALL\" then\n            if SETTINGS.ENABLE_UNLOCK_ALL then executeUnlockAll() end\n        end\n    end\n    \n    setupButton(btn, toggle)\n    return btn\nend\n\n-- ========== SLIDER ==========\nlocal function createSlider(text, min, max, setting, icon)\n    local container = Instance.new(\"Frame\")\n    container.Parent = scrollFrame\n    container.Size = UDim2.new(1, 0, 0, 65)\n    container.BackgroundTransparency = 1\n    \n    local label = Instance.new(\"TextLabel\")\n    label.Parent = container\n    label.Size = UDim2.new(1, 0, 0, 25)\n    label.Text = icon .. \" \" .. text .. \": \" .. tostring(SETTINGS[setting])\n    label.BackgroundTransparency = 1\n    label.TextColor3 = Color3.fromRGB(220, 210, 255)\n    label.Font = Enum.Font.GothamBold\n    label.TextSize = 13\n    label.TextXAlignment = Enum.TextXAlignment.Left\n    \n    local sliderBg = Instance.new(\"Frame\")\n    sliderBg.Parent = container\n    sliderBg.Size = UDim2.new(1, 0, 0, 35)\n    sliderBg.Position = UDim2.new(0, 0, 0, 28)\n    sliderBg.BackgroundColor3 = Color3.fromRGB(35, 30, 50)\n    \n    local bgCorner = Instance.new(\"UICorner\", sliderBg)\n    bgCorner.CornerRadius = UDim.new(0, 10)\n    \n    local fill = Instance.new(\"Frame\")\n    fill.Parent = sliderBg\n    fill.BackgroundColor3 = Color3.fromRGB(140, 60, 220)\n    fill.BorderSizePixel = 0\n    \n    local fillCorner = Instance.new(\"UICorner\", fill)\n    fillCorner.CornerRadius = UDim.new(0, 10)\n    \n    local initialVal = (SETTINGS[setting] - min) / (max - min)\n    fill.Size = UDim2.new(initialVal, 0, 1, 0)\n    \n    local dragging = false\n    \n    local function updateValue(inputPos)\n        local sliderPos = sliderBg.AbsolutePosition.X\n        local sliderWidth = sliderBg.AbsoluteSize.X\n        if sliderWidth <= 0 then return end\n        \n        local pos = math.clamp((inputPos - sliderPos) / sliderWidth, 0, 1)\n        local val = math.floor(min + (max - min) * pos)\n        \n        fill.Size = UDim2.new(pos, 0, 1, 0)\n        label.Text = icon .. \" \" .. text .. \": \" .. val\n        SETTINGS[setting] = val\n        \n        if setting == \"FOV\" then\n            updateCircleSize()\n        elseif setting == \"FLY_SPEED\" then\n            flySpeed = val\n            if flyEnabled and bodyVelocity then\n                local char = lp.Character\n                if char then\n                    local hum = char:FindFirstChildOfClass(\"Humanoid\")\n                    if hum and hum.MoveDirection.Magnitude > 0 then\n                        bodyVelocity.Velocity = hum.MoveDirection * val\n                    end\n                end\n            end\n        end\n    end\n    \n    sliderBg.InputBegan:Connect(function(input)\n        if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then\n            dragging = true\n            updateValue(input.Position.X)\n        end\n    end)\n    \n    UserInputService.InputChanged:Connect(function(input)\n        if dragging then\n            if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseMovement then\n                updateValue(input.Position.X)\n            end\n        end\n    end)\n    \n    UserInputService.InputEnded:Connect(function(input)\n        if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then\n            dragging = false\n        end\n    end)\n    \n    return container\nend\n\n-- ========== BOUTONS PRINCIPAUX ==========\ncreateButton(\"AIM SNAP\", \"ENABLE_LOCK\", \"🎯\")\ncreateButton(\"XRAY VISION\", \"ENABLE_XRAY\", \"👁️\")\ncreateButton(\"INFINITE JUMP\", \"ENABLE_INFJUMP\", \"🦘\")\ncreateButton(\"FLY MODE\", \"ENABLE_FLY\", \"🕊️\")\ncreateButton(\"NOCLIP\", \"ENABLE_NOCLIP\", \"🌀\")\ncreateButton(\"ESP PLAYERS\", \"ENABLE_ESP\", \"👤\")\ncreateButton(\"TRACERS\", \"ENABLE_TRACERS\", \"📏\")\ncreateButton(\"DARK TEXTURE\", \"ENABLE_DARK_TEXTURE\", \"🌑\")\ncreateButton(\"UNLOCK ALL\", \"ENABLE_UNLOCK_ALL\", \"🔓\")\ncreateSlider(\"FOV RANGE\", 50, 400, \"FOV\", \"🎯\")\ncreateSlider(\"FLY SPEED\", 20, 200, \"FLY_SPEED\", \"⚡\")\n\n-- ========== BOUTON TELEPORT FOLLOW ==========\nlocal followBtn = Instance.new(\"TextButton\")\nfollowBtn.Parent = scrollFrame\nfollowBtn.Size = UDim2.new(1, 0, 0, 45)\nfollowBtn.BackgroundColor3 = Color3.fromRGB(35, 30, 50)\nfollowBtn.Text = \"👣 TELEPORT FOLLOW\"\nfollowBtn.TextColor3 = Color3.fromRGB(255, 255, 255)\nfollowBtn.Font = Enum.Font.GothamBold\nfollowBtn.TextSize = 14\nlocal followCorner = Instance.new(\"UICorner\", followBtn)\nfollowCorner.CornerRadius = UDim.new(0, 10)\n\nsetupButton(followBtn, function()\n    if followActive then\n        stopFollow()\n    else\n        startFollow()\n    end\nend)\n\n-- ========== SLIDER FOLLOW HEIGHT ==========\ncreateSlider(\"FOLLOW HEIGHT\", 1, 30, \"FOLLOW_HEIGHT\", \"📏\")\n\n-- ========== FPS BOOST ==========\nlocal function optimizeFPS()\n    pcall(function()\n        for _, v in pairs(workspace:GetDescendants()) do\n            if v:IsA(\"Decal\") or v:IsA(\"Texture\") then v:Destroy() end\n            if v:IsA(\"ParticleEmitter\") or v:IsA(\"Trail\") or v:IsA(\"Fire\") or v:IsA(\"Smoke\") or v:IsA(\"Sparkles\") then v:Destroy() end\n            if v:IsA(\"PointLight\") or v:IsA(\"SpotLight\") or v:IsA(\"SurfaceLight\") then v:Destroy() end\n            if v:IsA(\"BloomEffect\") or v:IsA(\"BlurEffect\") or v:IsA(\"SunRaysEffect\") then v:Destroy() end\n            if v:IsA(\"Water\") then v.Material = Enum.Material.SmoothPlastic end\n        end\n        \n        local sky = workspace:FindFirstChildOfClass(\"Sky\")\n        if sky then sky:Destroy() end\n        \n        Lighting.ClockTime = 12\n        Lighting.GlobalShadows = false\n        Lighting.Brightness = 1\n        Lighting.Ambient = Color3.fromRGB(80, 80, 80)\n    end)\nend\n\nlocal fpsBtn = Instance.new(\"TextButton\")\nfpsBtn.Parent = scrollFrame\nfpsBtn.Size = UDim2.new(1, 0, 0, 45)\nfpsBtn.Text = \"⚡ FPS BOOST EXTREME\"\nfpsBtn.BackgroundColor3 = Color3.fromRGB(200, 80, 50)\nfpsBtn.TextColor3 = Color3.fromRGB(255, 255, 255)\nfpsBtn.Font = Enum.Font.GothamBold\nfpsBtn.TextSize = 14\nlocal fpsCorner = Instance.new(\"UICorner\", fpsBtn)\nfpsCorner.CornerRadius = UDim.new(0, 10)\nsetupButton(fpsBtn, optimizeFPS)\n\n-- ========== REMOVE SCRIPT ==========\nlocal removeBtn = Instance.new(\"TextButton\")\nremoveBtn.Parent = scrollFrame\nremoveBtn.Size = UDim2.new(1, 0, 0, 45)\nremoveBtn.Text = \"🗑️ REMOVE SCRIPT\"\nremoveBtn.BackgroundColor3 = Color3.fromRGB(180, 40, 40)\nremoveBtn.TextColor3 = Color3.fromRGB(255, 255, 255)\nremoveBtn.Font = Enum.Font.GothamBold\nremoveBtn.TextSize = 14\nlocal removeCorner = Instance.new(\"UICorner\", removeBtn)\nremoveCorner.CornerRadius = UDim.new(0, 10)\n\nsetupButton(removeBtn, function()\n    stopFollow()\n    stopFly()\n    stopNoclip()\n    stopDarkTexture()\n    if espFolder then espFolder:Destroy() end\n    if screenGui then screenGui:Destroy() end\n    if circleGui then circleGui:Destroy() end\n    RunService:UnbindFromRenderStep(\"NoksVIP_AimSnap\")\n    for _, conn in pairs(espConnections) do\n        if conn then conn:Disconnect() end\n    end\n    for _, line in pairs(tracerLines) do\n        if line then line:Remove() end\n    end\nend)\n\nuiList:GetPropertyChangedSignal(\"AbsoluteContentSize\"):Connect(function()\n    scrollFrame.CanvasSize = UDim2.new(0, 0, 0, uiList.AbsoluteContentSize.Y + 10)\nend)\n\nsetupButton(minBtn, function()\n    mainPanel.Visible = false\n    floatingBtn.Visible = true\nend)\nsetupButton(closeBtn, function()\n    mainPanel.Visible = false\n    floatingBtn.Visible = true\nend)\nsetupButton(floatingBtn, function()\n    mainPanel.Visible = true\n    floatingBtn.Visible = false\nend)\n\n-- ========== INFINITE JUMP ==========\nUserInputService.JumpRequest:Connect(function()\n    if SETTINGS.ENABLE_INFJUMP and lp.Character and not SETTINGS.ENABLE_FLY then\n        local hum = lp.Character:FindFirstChildOfClass(\"Humanoid\")\n        if hum and hum:GetState() ~= Enum.HumanoidStateType.Jumping then\n            hum:ChangeState(Enum.HumanoidStateType.Jumping)\n        end\n    end\nend)\n\n-- ========== ESP ==========\nlocal function createTracer(plr)\n    local line = Drawing.new(\"Line\")\n    line.Visible = false\n    line.Color = Color3.fromRGB(140, 60, 220)\n    line.Thickness = 2\n    line.Transparency = 0.7\n    return line\nend\n\nlocal function cleanESP(plr)\n    if espFolder:FindFirstChild(plr.Name) then\n        espFolder[plr.Name]:Destroy()\n    end\n    if highlights[plr] then\n        highlights[plr]:Destroy()\n        highlights[plr] = nil\n    end\n    if tracerLines[plr] then\n        tracerLines[plr]:Remove()\n        tracerLines[plr] = nil\n    end\n    if espConnections[plr] then\n        espConnections[plr]:Disconnect()\n        espConnections[plr] = nil\n    end\nend\n\nlocal function applyESP(plr)\n    if plr == lp then return end\n    \n    cleanESP(plr)\n    \n    local function setupESP(character)\n        if not character then return end\n        local hrp = character:FindFirstChild(\"HumanoidRootPart\")\n        if not hrp then return end\n        \n        local bg = Instance.new(\"BillboardGui\")\n        bg.Name = plr.Name\n        bg.Parent = espFolder\n        bg.AlwaysOnTop = true\n        bg.Size = UDim2.new(5, 0, 2.5, 0)\n        bg.StudsOffset = Vector3.new(0, 2.5, 0)\n        bg.ResetOnSpawn = false\n        \n        local nameLabel = Instance.new(\"TextLabel\", bg)\n        nameLabel.Size = UDim2.new(1, 0, 0.4, 0)\n        nameLabel.BackgroundTransparency = 1\n        nameLabel.Text = plr.Name\n        nameLabel.TextColor3 = Color3.fromRGB(255, 255, 255)\n        nameLabel.Font = Enum.Font.GothamBold\n        nameLabel.TextScaled = true\n        \n        local healthBarBg = Instance.new(\"Frame\", bg)\n        healthBarBg.Size = UDim2.new(0.8, 0, 0.15, 0)\n        healthBarBg.Position = UDim2.new(0.1, 0, 0.45, 0)\n        healthBarBg.BackgroundColor3 = Color3.fromRGB(50, 45, 70)\n        \n        local healthBar = Instance.new(\"Frame\", healthBarBg)\n        healthBar.Size = UDim2.new(1, 0, 1, 0)\n        healthBar.BackgroundColor3 = Color3.fromRGB(140, 60, 220)\n        \n        local tracer = createTracer(plr)\n        tracerLines[plr] = tracer\n        \n        local renderConn = RunService.RenderStepped:Connect(function()\n            if not plr.Character or not plr.Character:FindFirstChild(\"HumanoidRootPart\") then\n                bg.Enabled = false\n                if tracer then tracer.Visible = false end\n                return\n            end\n            \n            local hum = plr.Character:FindFirstChildOfClass(\"Humanoid\")\n            if hum and hum.Health > 0 then\n                local healthPercent = hum.Health / hum.MaxHealth\n                healthBar.Size = UDim2.new(healthPercent, 0, 1, 0)\n                bg.Enabled = true\n                bg.Adornee = hrp\n                \n                if healthPercent > 0.6 then\n                    healthBar.BackgroundColor3 = Color3.fromRGB(0, 255, 0)\n                elseif healthPercent > 0.3 then\n                    healthBar.BackgroundColor3 = Color3.fromRGB(255, 165, 0)\n                else\n                    healthBar.BackgroundColor3 = Color3.fromRGB(255, 0, 0)\n                end\n            else\n                bg.Enabled = false\n            end\n            \n            if SETTINGS.ENABLE_TRACERS and plr.Character and plr.Character:FindFirstChild(\"Head\") then\n                local hum = plr.Character:FindFirstChildOfClass(\"Humanoid\")\n                if hum and hum.Health > 0 then\n                    local head = plr.Character.Head\n                    local screenPos, onScreen = cam:WorldToViewportPoint(head.Position)\n                    if onScreen and tracer then\n                        tracer.From = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y)\n                        tracer.To = Vector2.new(screenPos.X, screenPos.Y)\n                        tracer.Visible = true\n                    else\n                        tracer.Visible = false\n                    end\n                else\n                    tracer.Visible = false\n                end\n            elseif tracer then\n                tracer.Visible = false\n            end\n        end)\n        \n        espConnections[plr] = renderConn\n        \n        if SETTINGS.ENABLE_XRAY then\n            local hl = Instance.new(\"Highlight\")\n            hl.FillColor = Color3.fromRGB(140, 60, 220)\n            hl.FillTransparency = 0.6\n            hl.Adornee = character\n            hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop\n            hl.Parent = character\n            highlights[plr] = hl\n        end\n    end\n    \n    if plr.Character then\n        setupESP(plr.Character)\n    end\n    \n    plr.CharacterAdded:Connect(function(character)\n        task.wait(0.5)\n        setupESP(character)\n    end)\nend\n\nlocal function refreshESP()\n    for _, plr in pairs(Players:GetPlayers()) do\n        if plr ~= lp then\n            cleanESP(plr)\n            applyESP(plr)\n        end\n    end\nend\n\nfor _, plr in pairs(Players:GetPlayers()) do\n    task.spawn(function() applyESP(plr) end)\nend\n\nPlayers.PlayerAdded:Connect(applyESP)\nPlayers.PlayerRemoving:Connect(function(plr)\n    cleanESP(plr)\nend)\n\n-- ========== AIM SNAP ==========\nlocal function isPlayerAlive(plr)\n    if not plr.Character then return false end\n    local hum = plr.Character:FindFirstChildOfClass(\"Humanoid\")\n    return hum and hum.Health > 0\nend\n\nlocal function getTargetInFOV()\n    local center = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)\n    local bestTarget = nil\n    local bestDist = SETTINGS.FOV / 2\n    \n    for _, plr in pairs(Players:GetPlayers()) do\n        if plr ~= lp and isPlayerAlive(plr) and plr.Character and plr.Character:FindFirstChild(\"Head\") then\n            local head = plr.Character.Head\n            local screenPos, onScreen = cam:WorldToViewportPoint(head.Position)\n            \n            if onScreen then\n                local raycastParams = RaycastParams.new()\n                raycastParams.FilterType = Enum.RaycastFilterType.Blacklist\n                raycastParams.FilterDescendantsInstances = {lp.Character}\n                local ray = workspace:Raycast(cam.CFrame.Position, (head.Position - cam.CFrame.Position), raycastParams)\n                local visible = not ray or ray.Instance:IsDescendantOf(plr.Character)\n                \n                if visible then\n                    local dist = (Vector2.new(screenPos.X, screenPos.Y) - center).Magnitude\n                    if dist <= bestDist then\n                        bestDist = dist\n                        bestTarget = head\n                    end\n                end\n            end\n        end\n    end\n    \n    return bestTarget\nend\n\nRunService:BindToRenderStep(\"NoksVIP_AimSnap\", Enum.RenderPriority.Camera.Value + 1, function()\n    if not SETTINGS.ENABLE_LOCK then return end\n    if followActive then return end\n    \n    local char = lp.Character\n    if not char then return end\n    \n    local target = getTargetInFOV()\n    \n    if target then\n        local currentPos = cam.CFrame.Position\n        cam.CFrame = CFrame.new(currentPos, target.Position)\n    end\nend)\n\nprint(\"✅ NOKS VIP - Script chargé avec Dark Texture et Unlock All\")\n\n")()
